fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both vectors simultaneously
    for (x, y) in a.iter().zip(b.iter()) {
        // Push the result of the inequality check into the result vector
        result.push(x != y);
    }
    
    result
}